import React from 'react'
import {connect} from 'react-redux'
import PropTypes from 'prop-types'
import {auth} from '../store'
import {FaUserPlus} from 'react-icons/fa'

/**
 * COMPONENT
 */
const AuthForm = props => {
  const {name, displayName, handleSubmit, error} = props

  return (
    <div className="Signup-form-container">
      <form onSubmit={handleSubmit} name={name} className="Signup-form">
        <div className="signup-icon">
          <FaUserPlus />
        </div>
        <h2>Sign-up</h2>
        <div className="top-label-signup">
          <label className="label2" htmlFor="name">
            User Name
          </label>
          <br />
          <input name="name" type="text" />
        </div>
        <div>
          <label className="label2" htmlFor="email">
            Email
          </label>
          <br />
          <input name="email" type="text" />
        </div>
        <div>
          <label className="label2" htmlFor="password">
            Password
          </label>
          <br />
          <input name="password" type="password" />
        </div>
        <br />
        <div className="button-log-sign">
          <button type="submit">{displayName}</button>
        </div>
        <br />
        {error &&
          error.response && (
            <div className="log-error"> {error.response.data} </div>
          )}
        <div className="google-log">
          <a href="/auth/google">{displayName} with Google</a>
        </div>
      </form>
    </div>
  )
}

/**
 * CONTAINER
 *   Note that we have two different sets of 'mapStateToProps' functions -
 *   one for Login, and one for Signup. However, they share the same 'mapDispatchToProps'
 *   function, and share the same Component. This is a good example of how we
 *   can stay DRY with interfaces that are very similar to each other!
 */
// const mapLogin = state => {
//   return {
//     name: 'login',
//     displayName: 'Login',
//     error: state.user.error
//   }
// }

const mapSignup = state => {
  return {
    name: 'signup',
    displayName: 'Sign Up',
    error: state.user.error
  }
}

const mapDispatch = dispatch => {
  return {
    handleSubmit(evt) {
      evt.preventDefault()
      const formName = evt.target.name
      const email = evt.target.email.value
      const password = evt.target.password.value
      dispatch(auth(email, password, formName))
    }
  }
}

// export const Login = connect(mapLogin, mapDispatch)(AuthForm)
export const Signup = connect(mapSignup, mapDispatch)(AuthForm)

/**
 * PROP TYPES
 */
AuthForm.propTypes = {
  name: PropTypes.string.isRequired,
  displayName: PropTypes.string.isRequired,
  handleSubmit: PropTypes.func.isRequired,
  error: PropTypes.object
}
